package org.viridexa.api.account;
import java.net.*;import java.net.http.*;import java.sql.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.test.context.*;import org.springframework.boot.json.JsonParserFactory;
import static org.junit.jupiter.api.Assertions.*;
/** Disposable technical identities only; refuses the production schema. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class AccountMySqlIT {
 @LocalServerPort int port;
 static String env(String k){String v=System.getenv(k);if(v==null||v.isBlank())throw new IllegalStateException("Missing isolated account environment");return v;}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){if(!env("GOVERNANCE_TEST_SCHEMA").startsWith("viridexa_governance_test_"))throw new IllegalStateException("Production forbidden");r.add("spring.datasource.url",()->env("GOVERNANCE_TEST_DB_URL"));r.add("spring.datasource.username",()->env("GOVERNANCE_TEST_RO"));r.add("spring.datasource.password",()->env("GOVERNANCE_TEST_PASSWORD"));r.add("spring.flyway.user",()->env("GOVERNANCE_TEST_MIGRATOR"));r.add("spring.flyway.password",()->env("GOVERNANCE_TEST_PASSWORD"));r.add("viridexa.review.username",()->env("GOVERNANCE_TEST_WRITER"));r.add("viridexa.review.password",()->env("GOVERNANCE_TEST_PASSWORD"));r.add("viridexa.accounts.username",()->env("GOVERNANCE_TEST_ACCOUNT"));r.add("viridexa.accounts.password",()->env("GOVERNANCE_TEST_PASSWORD"));}
 Connection db(String user)throws Exception{return DriverManager.getConnection(env("GOVERNANCE_TEST_DB_URL"),user,env("GOVERNANCE_TEST_PASSWORD"));}
 void sql(String q)throws Exception{try(var c=db(env("GOVERNANCE_TEST_MIGRATOR"));var s=c.createStatement()){s.execute(q);}}
 String scalar(String q)throws Exception{try(var c=db(env("GOVERNANCE_TEST_MIGRATOR"));var s=c.createStatement();var r=s.executeQuery(q)){assertTrue(r.next());return r.getString(1);}}
 HttpClient client(){return HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();}
 String cookie(HttpClient c){return ((CookieManager)c.cookieHandler().orElseThrow()).getCookieStore().getCookies().stream().filter(x->x.getName().equals("JSESSIONID")).map(HttpCookie::getValue).findFirst().orElse("");}
 HttpResponse<String> get(HttpClient c,String p)throws Exception{return c.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+p)).GET().build(),HttpResponse.BodyHandlers.ofString());}
 Map<String,Object> object(String s){return JsonParserFactory.getJsonParser().parseMap(s);}
 String csrf(HttpClient c)throws Exception{return (String)object(get(c,"/api/v1/csrf").body()).get("token");}
 HttpResponse<String> post(HttpClient c,String p,String b,boolean token)throws Exception{var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+p)).header("Content-Type","application/json");if(token)r.header("X-CSRF-TOKEN",csrf(c));return c.send(r.POST(HttpRequest.BodyPublishers.ofString(b)).build(),HttpResponse.BodyHandlers.ofString());}
 String mail(){return "public-fixture-"+UUID.randomUUID()+"@example.invalid";}
 String registration(String e){return "{\"email\":\""+e+"\",\"displayName\":\"技术测试小树\",\"password\":\""+env("GOVERNANCE_FIXTURE_PASSWORD")+"\"}";}
 String login(String e,String password){return "{\"email\":\""+e+"\",\"password\":\""+password+"\"}";}
 @AfterEach void clean()throws Exception{sql("UPDATE app_role SET role_key='MEMBER' WHERE role_key='MEMBER_HOLD'");sql("DELETE ur FROM user_role ur JOIN app_user u ON u.id=ur.user_id WHERE u.email LIKE 'public-fixture-%@example.invalid'");sql("DELETE FROM app_user WHERE email LIKE 'public-fixture-%@example.invalid'");}
 @Test void registrationCreatesOnlyMemberAndRotatesSession()throws Exception{String e=mail();var c=client();String oldToken=csrf(c),oldCookie=cookie(c);var r=post(c,"/api/v1/account/register",registration(e),true);assertEquals(201,r.statusCode(),r.body());assertNotEquals(oldCookie,cookie(c));assertEquals(List.of("MEMBER"),object(r.body()).get("roles"));assertFalse(r.body().contains("password"));assertEquals("NOT_CONFIGURED",object(r.body()).get("emailVerification"));assertTrue(r.headers().firstValue("Cache-Control").orElse("").contains("no-store"));assertTrue(scalar("SELECT password_hash FROM app_user WHERE email='"+e+"'").startsWith("$2"));assertEquals(200,get(c,"/api/v1/account/session").statusCode());assertEquals(401,get(client(),"/api/v1/account/session").statusCode());assertNotEquals(oldToken,csrf(c));assertEquals(204,post(c,"/api/v1/account/logout","{}",true).statusCode());assertEquals(401,get(c,"/api/v1/account/session").statusCode());}
 @Test void duplicateNormalizedEmailAndInjectedRolesDoNotEscalate()throws Exception{String e=mail();assertEquals(201,post(client(),"/api/v1/account/register",registration(e.toUpperCase(Locale.ROOT)),true).statusCode());assertEquals(409,post(client(),"/api/v1/account/register",registration(e),true).statusCode());assertEquals("1",scalar("SELECT COUNT(*) FROM app_user WHERE email='"+e+"'"));String other=mail();assertEquals(400,post(client(),"/api/v1/account/register",registration(other).replace("}",",\"roles\":[\"ADMIN\"]}"),true).statusCode());assertEquals("0",scalar("SELECT COUNT(*) FROM app_user WHERE email='"+other+"'"));}
 @Test void missingMemberRoleRollsBackAndWriterCannotInsertArbitraryRoles()throws Exception{String e=mail();sql("UPDATE app_role SET role_key='MEMBER_HOLD' WHERE role_key='MEMBER'");assertEquals(503,post(client(),"/api/v1/account/register",registration(e),true).statusCode());assertEquals("0",scalar("SELECT COUNT(*) FROM app_user WHERE email='"+e+"'"));try(var c=db(env("GOVERNANCE_TEST_ACCOUNT"));var s=c.createStatement()){assertThrows(SQLException.class,()->s.execute("INSERT INTO user_role(user_id,role_id) SELECT u.id,r.id FROM app_user u CROSS JOIN app_role r LIMIT 1"));assertThrows(SQLException.class,()->s.execute("UPDATE scientific_candidate SET reason='FORBIDDEN'"));}}
 @Test void publicLoginDoesNotGrantReviewAndDisabledAccountsAreRejected()throws Exception{String e=mail();var c=client();assertEquals(201,post(c,"/api/v1/account/register",registration(e),true).statusCode());assertEquals(403,get(c,"/api/v1/admin/science/catalog").statusCode());assertEquals(403,post(c,"/api/v1/admin/session", "{\"username\":\""+e+"\",\"password\":\""+env("GOVERNANCE_FIXTURE_PASSWORD")+"\"}",true).statusCode());post(c,"/api/v1/account/logout","{}",true);assertEquals(401,post(c,"/api/v1/account/login",login(e,"wrong-password"),true).statusCode());assertEquals(200,post(c,"/api/v1/account/login",login(e,env("GOVERNANCE_FIXTURE_PASSWORD")),true).statusCode());sql("UPDATE app_user SET enabled=FALSE WHERE email='"+e+"'");assertEquals(401,get(c,"/api/v1/account/session").statusCode());assertEquals(401,post(client(),"/api/v1/account/login",login(e,env("GOVERNANCE_FIXTURE_PASSWORD")),true).statusCode());}
 @Test void concurrentSameEmailHasOneCompleteAccount()throws Exception{String e=mail();var a=client();var b=client();csrf(a);csrf(b);var executor=Executors.newFixedThreadPool(2);try{var f=executor.invokeAll(List.of((Callable<Integer>)()->post(a,"/api/v1/account/register",registration(e),true).statusCode(),()->post(b,"/api/v1/account/register",registration(e),true).statusCode()));var codes=new ArrayList<Integer>();for(var x:f)codes.add(x.get());Collections.sort(codes);assertEquals(List.of(201,409),codes);assertEquals("1",scalar("SELECT COUNT(*) FROM user_role ur JOIN app_user u ON u.id=ur.user_id JOIN app_role r ON r.id=ur.role_id WHERE u.email='"+e+"' AND r.role_key='MEMBER'"));}finally{executor.shutdownNow();}}
 @Test void publicEndpointsStillRequireCsrfAndRejectLoggedInRegistration()throws Exception{var c=client();String e=mail();assertEquals(403,post(c,"/api/v1/account/register",registration(e),false).statusCode());assertEquals(201,post(c,"/api/v1/account/register",registration(e),true).statusCode());assertEquals(409,post(c,"/api/v1/account/register",registration(mail()),true).statusCode());assertEquals(403,post(c,"/api/v1/account/logout","{}",false).statusCode());}
 @Test void administratorsCanUseTheSameLoginWithoutLosingRoleBoundary()throws Exception{var c=client();assertEquals(200,post(c,"/api/v1/account/login",login("automated-isolated-fixture@example.invalid",env("GOVERNANCE_FIXTURE_PASSWORD")),true).statusCode());assertEquals(200,get(c,"/api/v1/admin/session").statusCode());assertTrue(get(c,"/api/v1/account/session").body().contains("ADMIN"));}
}
